/*
 * Copy www/ -> android/app/src/main/assets/public/
 *
 * The Android build does not run `cap sync`, so assets/public is what actually
 * ships inside the APK. Doing this by hand is how stale code gets packaged.
 *
 * Run: npm run sync
 */

'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'www');
const DEST = path.join(ROOT, 'android', 'app', 'src', 'main', 'assets', 'public');

// Generated by Capacitor, not sourced from www/ -- leave them alone.
const KEEP = /^cordova(_plugins)?\.js$/;

fs.mkdirSync(DEST, { recursive: true });

const webFiles = fs.readdirSync(SRC).filter((f) => /\.(html|js|css)$/i.test(f));
let copied = 0;

for (const f of webFiles) {
  fs.copyFileSync(path.join(SRC, f), path.join(DEST, f));
  console.log('  copied  ' + f);
  copied++;
}

// Drop anything left behind by a rename, so a deleted/renamed file can't keep
// answering from inside the APK.
for (const f of fs.readdirSync(DEST)) {
  if (!/\.(html|js|css)$/i.test(f) || KEEP.test(f)) continue;
  if (!fs.existsSync(path.join(SRC, f))) {
    fs.unlinkSync(path.join(DEST, f));
    console.log('  removed ' + f + '  (no longer in www/)');
  }
}

console.log(`\n${copied} web assets synced into the APK assets.`);
